{
  "$schema": "./node_modules/oxlint/configuration_schema.json",
  "extends": ["../../.config/oxlint/brunch/react.json"],
  "categories": {
    "correctness": "error",
    "perf": "warn"
  },
  "options": {
    "typeAware": true,
    "typeCheck": true
  },
  "env": {
    "builtin": true,
    "es2026": true,
    "node": true
  },
  "settings": {
    "react": {
      "version": "19.2"
    }
  },
  "rules": {
    "no-restricted-imports": [
      "error",
      {
        "paths": [
          {
            "name": "@hashintel/petrinaut",
            "message": "The Brunch server must remain independent of Petrinaut UI. Import catalogs from @hashintel/petrinaut-core, not the editor package."
          }
        ],
        "patterns": [
          {
            "group": ["@local/*"],
            "message": "The Brunch application must not depend on unpublished HASH packages."
          },
          {
            "group": [
              "@hashintel/petrinaut/*",
              "@hashintel/petrinaut-cli",
              "@hashintel/petrinaut-cli/*"
            ],
            "message": "The Brunch server must remain independent of Petrinaut UI and CLI. Import catalogs from @hashintel/petrinaut-core, not the editor package."
          }
        ]
      }
    ]
  },
  "overrides": [
    {
      "files": ["src/ui/**/*.{ts,tsx}"],
      "env": {
        "browser": true
      }
    }
  ],
  "ignorePatterns": [
    "dist/**",
    "build/**",
    "coverage/**",
    "*.gen.*",
    "*.tsbuildinfo",
    ".turbo/**"
  ]
}

import { defineConfig } from "@flue/runtime/config";

export default defineConfig({
  target: "node",
  // Exhaustive, so a typo'd provider fails at resolution instead of reaching
  // the network (Flue patterns audit, 2026-08-17).
  providers: ["anthropic"],
});

/**
 * Local FE-1436 panel launcher.
 *
 * Loads the real hash Petrinaut website config, removes only its incumbent
 * `/api/chat` dev handler, and sends that same-origin route to brunch's
 * committed application server. The real panel, wrappers, and editor stay untouched;
 * hash's tracked checkout stays clean.
 */

import { join, resolve } from "node:path";

import {
  defineConfig,
  loadConfigFromFile,
  mergeConfig,
  type PluginOption,
} from "vite";

import {
  defaultChatOrigin,
  petrinautLocalServer,
} from "./src/local-dev-origins.ts";

const withoutIncumbentChatHandler = (
  plugins: readonly PluginOption[],
): PluginOption[] =>
  plugins.filter((plugin) => {
    if (
      plugin === false ||
      plugin === null ||
      plugin === undefined ||
      Array.isArray(plugin) ||
      typeof plugin !== "object" ||
      !("name" in plugin)
    ) {
      return true;
    }
    return plugin.name !== "petrinaut-api-dev";
  });

export default defineConfig(async (environment) => {
  const websiteRoot = process.env.PETRINAUT_WEBSITE_ROOT;
  if (!websiteRoot) {
    throw new Error("PETRINAUT_WEBSITE_ROOT is required.");
  }
  const root = resolve(websiteRoot);
  // Babel resolves the React compiler plugin from the launched project's cwd,
  // not from the imported config file. Match a native hash launch before the
  // plugin begins transforming the real panel source.
  process.chdir(root);
  const loaded = await loadConfigFromFile(
    environment,
    join(root, "vite.config.ts"),
    root,
  );
  if (!loaded)
    throw new Error(`Could not load Petrinaut's Vite config from ${root}.`);

  const chatOrigin = process.env.BRUNCH_CHAT_ORIGIN ?? defaultChatOrigin;
  return mergeConfig(
    {
      ...loaded.config,
      plugins: withoutIncumbentChatHandler(loaded.config.plugins ?? []),
    },
    {
      root,
      server: petrinautLocalServer(chatOrigin),
    },
  );
});

/** Hono middleware: the mounted Flue route enforces the same ownership rule as `/api/chat`. */

import { BRUNCH_PRINCIPAL_HEADER } from "@hashintel/brunch-agent-transport-aisdk/headers";

import { ownsFlueInstance } from "./conversation-identity.ts";
import { BRUNCH_CONVERSATION_HEADER } from "./conversation-payload.ts";

import type { MiddlewareHandler } from "hono";

export const agentOwnershipGuard = (mountPrefix: string): MiddlewareHandler => {
  return async (context, next) => {
    const principalKey = context.req.header(BRUNCH_PRINCIPAL_HEADER)?.trim();
    const conversationId = context.req
      .header(BRUNCH_CONVERSATION_HEADER)
      ?.trim();
    if (
      principalKey === undefined ||
      principalKey.length === 0 ||
      conversationId === undefined ||
      conversationId.length === 0
    ) {
      return context.json({ error: "unauthorized" }, 401);
    }
    const instanceId = context.req.path
      .slice(mountPrefix.length)
      .split("/")
      .find((segment) => segment.length > 0);
    if (
      instanceId === undefined ||
      !ownsFlueInstance(principalKey, conversationId, instanceId)
    ) {
      return context.json({ error: "forbidden" }, 403);
    }
    return next();
  };
};

"use agent";
/**
 * One plain Flue chat agent for the Petrinaut panel throughline.
 *
 * Capture is a harness-side pipe, not an interviewer tool. One stub skill is
 * mounted so activation can appear in Flue history.
 */

import { defineSkill, useModel, useSkill, useTool } from "@flue/runtime";

import { ping } from "../tools/ping.ts";
import { readPetrinautDoc } from "../tools/read-petrinaut-doc.ts";

export const CHAT_MODEL_ID =
  process.env["BRUNCH_CHAT_MODEL"] || "claude-haiku-4-5";

export const STUB_SKILL_NAME = "confirm-path";

export const ACTIVATE_SKILL_TOOL_NAME = "activate_skill";

const confirmPath = defineSkill({
  name: STUB_SKILL_NAME,
  description:
    "Confirm how this assistant is mounted. Use when checking the server path or tool layout.",
  instructions:
    "Say that ping confirms the server tool path. Then continue helping the user.",
});

export function ChatAgent() {
  useModel(`anthropic/${CHAT_MODEL_ID}`);
  useSkill(confirmPath);
  useTool(ping);
  useTool(readPetrinautDoc);
  return [
    "You are a concise assistant inside the Petrinaut editor.",
    "Call ping when you need to confirm the server tool path.",
    `Activate the \`${STUB_SKILL_NAME}\` skill before calling ping.`,
    "When the user asks how Petrinaut's UI works, call readPetrinautDoc.",
    "A client-tool-result signal is JSON [{ toolCallId, toolName, output }]. Treat output as the browser's result for that call and continue helping the user.",
  ].join("\n");
}

/**
 * Pinned, and never to be edited: conversation storage keys on this literal.
 */
ChatAgent.agentName = "brunch-chat-agent";

/**
 * The app's route map — one plain Flue chat agent plus Petrinaut's /api/chat door.
 *
 * Both doors require principal + conversation id. `/api/chat` takes the principal
 * header and body `id`; `/agents/chat/:id` takes the same principal plus
 * `x-brunch-conversation` and admits the request only when those re-derive the
 * path id. The Flue instance id is derived, not a bearer token.
 */

import { readFile } from "node:fs/promises";

import { createOpenTelemetryInstrumentation } from "@flue/opentelemetry";
import { instrument } from "@flue/runtime";
import { createAgentRouter } from "@flue/runtime/routing";
import { Hono } from "hono";

import { agentOwnershipGuard } from "./agent-ownership.ts";
import { ChatAgent } from "./agents/chat-agent.ts";
import { assetHandler } from "./assets.ts";
import { petrinautChatHandler } from "./petrinaut-chat.ts";
import { CHAT_AGENT_ROUTE, PETRINAUT_CHAT_ROUTE } from "./routes.ts";

instrument(createOpenTelemetryInstrumentation({ content: false }));

const app = new Hono();

const chatAgentMount = `/agents/${CHAT_AGENT_ROUTE}`;
app.use(`${chatAgentMount}/*`, agentOwnershipGuard(`${chatAgentMount}/`));
app.route(chatAgentMount, createAgentRouter(ChatAgent));

app.on(["GET", "POST", "OPTIONS"], PETRINAUT_CHAT_ROUTE, (c) =>
  petrinautChatHandler(c.req.raw),
);

const uiRoot = new URL(
  // oxlint-disable-next-line typescript/no-unnecessary-condition -- import.meta.env is absent when Node executes this module directly.
  import.meta.env?.DEV === false ? "./client/" : "../",
  import.meta.url,
);

app.get("/", async (c) =>
  c.html(await readFile(new URL("index.html", uiRoot), "utf8")),
);

app.get("/assets/*", assetHandler(uiRoot));

export default app;

/**
 * Production asset serving — everything the client build emits, not an
 * extension allowlist and not a filename grammar.
 *
 * The FE-1361 review verified the failure the old inline route carried: it
 * allowlisted `js|css|map` and read hits as UTF-8, so the first font or image
 * the client build emitted would 404 in production while vite dev served it
 * fine — and widening the allowlist without dropping the UTF-8 read would
 * have corrupted binary bytes instead. So: any safe file name serves, read as
 * bytes; the content-type comes from hono's own MIME table and fails open to
 * `application/octet-stream` rather than failing the asset.
 *
 * What counts as safe is a property of the path, not a pattern the emitted
 * names are assumed to follow. `[name]` in a bundler's `assetFileNames` is the
 * source basename, so spaces, parentheses, accents, `+`, `,`, `'`, `#` and `?`
 * are all legal output, and a grammar narrower than the producer's is a
 * production-only 404 waiting for the first asset that uses one.
 *
 * Mounted as a wildcard (`/assets/*`) rather than `:file`, because a `:file`
 * param cannot match the nested paths bundlers emit (`assets/fonts/x.woff2`).
 */

import { readFile } from "node:fs/promises";

import { getMimeType } from "hono/utils/mime";

import type { Context } from "hono";

/**
 * Read failures that mean "no file at this path, and none can be": absent,
 * reached through a file, a directory rather than a file, or too long to name
 * one. Every other failure — a permission problem, a symlink cycle, an I/O
 * error — is a fault to surface, because a 404 would report a broken build tree
 * as an asset that was simply never emitted.
 */
const ABSENT_PATH_CODES = new Set([
  "ENOENT",
  "ENOTDIR",
  "EISDIR",
  "ENAMETOOLONG",
]);

const isAbsentPath = (error: unknown): boolean =>
  error instanceof Error &&
  "code" in error &&
  ABSENT_PATH_CODES.has((error as NodeJS.ErrnoException).code ?? "");

/**
 * Whether a decoded path is safe to look up under the asset root: at least one
 * segment, none empty, none dot-led — which is what keeps `..` traversal and
 * hidden files out — no nul byte, which `readFile` rejects with a `TypeError`
 * rather than an errno, and an extension on the last segment.
 */
const isSafeAssetPath = (file: string): boolean => {
  if (file.includes("\0")) return false;
  const segments = file.split("/");
  return (
    segments.every(
      (segment) => segment.length > 0 && !segment.startsWith("."),
    ) && /\.[^./]+$/.test(segments.at(-1) ?? "")
  );
};

/** Serve `assets/*` from the client build rooted at `uiRoot`. */
export function assetHandler(uiRoot: URL): (c: Context) => Promise<Response> {
  return async (c) => {
    // The raw wildcard remainder, decoded here because hono decodes params
    // but not the path — an undecodable escape is a 404, not a crash.
    let file: string;
    try {
      file = decodeURIComponent(c.req.path.replace(/^\/assets\//, ""));
    } catch (error) {
      if (error instanceof URIError) return c.notFound();
      throw error;
    }
    if (!isSafeAssetPath(file)) return c.notFound();
    // Re-encoded segment by segment on the way into the URL: to the URL parser
    // `#` opens a fragment and `?` a query, and under the file: scheme a
    // backslash is a path separator, so a name carrying any of them addresses
    // some other file — `..\` addresses one outside the asset root entirely.
    const path = new URL(
      `assets/${file
        .split("/")
        .map((segment) => encodeURIComponent(segment))
        .join("/")}`,
      uiRoot,
    );
    // Served as read, with no intermediate copy. The cast is a type gap, not a
    // conversion: `readFile` is typed to admit a SharedArrayBuffer-backed view,
    // which hono's body type excludes, while the value it returns always owns
    // its own ArrayBuffer.
    let bytes: Uint8Array<ArrayBuffer>;
    try {
      bytes = (await readFile(path)) as Uint8Array<ArrayBuffer>;
    } catch (error) {
      if (isAbsentPath(error)) return c.notFound();
      throw error;
    }
    // Fail open on the content-type, never on the bytes: an extension the
    // table does not know degrades to a pickier content-type, not to a
    // production-only 404.
    return c.body(bytes, 200, {
      "content-type": getMimeType(file) ?? "application/octet-stream",
    });
  };
}

/**
 * Harness-side apply-sweep over a named Flue history range.
 *
 * The interviewer does not call this. A test or harness fact names the range.
 * Stub extraction: one envelope per user utterance, quote = that text, payload {}.
 */

import {
  createFlueHistoryReader,
  createLocalCaptureStore,
  projectFlueHistoryForSweep,
} from "@hashintel/brunch-agent-binding-flue";

import {
  agentOwnershipHeaders,
  flueConversationIdFrom,
  type ConversationIdentity,
} from "./conversation-identity.ts";
import { captureStorePath } from "./db-path.ts";
import { CHAT_AGENT_ROUTE } from "./routes.ts";

export interface CaptureSweepCapture {
  readonly id: string;
  readonly excerpt: string;
  readonly payload: unknown;
}

export interface CaptureSweepResult {
  readonly appliedCaptureIds: readonly string[];
  readonly skippedDedupKeys: readonly string[];
  readonly captures: readonly CaptureSweepCapture[];
}

const conversationUrl = (instanceId: string): string =>
  `http://brunch.local/agents/${CHAT_AGENT_ROUTE}/${instanceId}`;

const ownedTransport = (identity: ConversationIdentity): typeof fetch => {
  const ownership = agentOwnershipHeaders(identity);
  return async (input, init) => {
    const { default: app } = await import("./app.ts");
    const headers = new Headers(init?.headers);
    for (const [key, value] of Object.entries(ownership)) {
      headers.set(key, value);
    }
    return app.fetch(
      input instanceof Request
        ? new Request(input, { headers })
        : new Request(input, { ...init, headers }),
    );
  };
};

export const applyCaptureSweep = async (
  identity: ConversationIdentity,
  userEntryIds: readonly string[],
): Promise<CaptureSweepResult> => {
  const instanceId = flueConversationIdFrom(identity);
  const store = createLocalCaptureStore(captureStorePath(instanceId), {
    ownerKey: identity.principalKey,
  });
  const historyReader = createFlueHistoryReader({
    resolveConversationUrl: conversationUrl,
    transport: ownedTransport(identity),
    archive: store,
  });
  const snapshot = await historyReader.read(instanceId);
  const range = new Set(userEntryIds);
  const proposals = projectFlueHistoryForSweep(snapshot)
    .filter(
      (entry) =>
        entry.kind === "user" && range.has(entry.id) && entry.text.length > 0,
    )
    .map((entry) => ({
      evidence: [{ excerpt: entry.text }],
      epistemicStatus: "explicit" as const,
      confidence: "high",
      content: { value: {} },
    }));
  const applied = await store.execute(
    { type: "apply-sweep", proposals },
    { sessionId: instanceId },
  );
  if (!applied.ok) {
    throw new Error(
      `apply-sweep refused: ${applied.refusal.code}: ${applied.refusal.message}`,
    );
  }
  if (!("appliedCaptureIds" in applied.value)) {
    throw new Error("apply-sweep did not return a sweep value.");
  }
  return {
    appliedCaptureIds: applied.value.appliedCaptureIds,
    skippedDedupKeys: applied.value.skippedDedupKeys,
    captures: applied.snapshot.captures.map((capture) => ({
      id: capture.id,
      excerpt:
        "evidence" in capture ? (capture.evidence[0]?.excerpt ?? "") : "",
      payload:
        "value" in capture.content ? capture.content.value : capture.content,
    })),
  };
};

/** Flue-side client-tool signal contract: awaiting sentinel, result signal, tool names. */

import { readPetrinautDocToolName } from "@hashintel/petrinaut-core/ai";

export const CLIENT_TOOL_RESULT_SIGNAL = "client-tool-result";

export const AWAITING_CLIENT = "client" as const;

export const clientToolNames: ReadonlySet<string> = new Set([
  readPetrinautDocToolName,
]);

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null;

export const isAwaitingClient = (output: unknown): boolean =>
  isRecord(output) && output.awaiting === AWAITING_CLIENT;

export const providerExecutedFor = (clientTool: boolean): true | undefined =>
  clientTool ? undefined : true;

/** Browser-safe instance-id hash; must match `flueConversationId` byte-for-byte. */

import { hexFromDigest, identityPayload } from "./conversation-payload.ts";

export const flueConversationIdWeb = async (
  principalKey: string,
  conversationId: string,
): Promise<string> => {
  const payload = identityPayload(principalKey, conversationId);
  const bytes = new ArrayBuffer(payload.byteLength);
  new Uint8Array(bytes).set(payload);
  const digest = await globalThis.crypto.subtle.digest("SHA-256", bytes);
  return hexFromDigest(digest);
};

/** Stable Flue instance id for one principal + panel conversation. */

import { createHash, timingSafeEqual } from "node:crypto";

import {
  BRUNCH_CONVERSATION_HEADER,
  BRUNCH_PRINCIPAL_HEADER,
  identityPayload,
} from "./conversation-payload.ts";

import type { ConversationIdentity } from "@hashintel/brunch-agent-transport-aisdk";

export {
  BRUNCH_CONVERSATION_HEADER,
  BRUNCH_PRINCIPAL_HEADER,
  LOCAL_UI_PRINCIPAL,
} from "./conversation-payload.ts";
export type { ConversationIdentity };

export const flueConversationId = (
  principalKey: string,
  conversationId: string,
): string =>
  createHash("sha256")
    .update(identityPayload(principalKey, conversationId))
    .digest("hex");

export const flueConversationIdFrom = (
  identity: ConversationIdentity,
): string => flueConversationId(identity.principalKey, identity.conversationId);

export const ownsFlueInstance = (
  principalKey: string,
  conversationId: string,
  instanceId: string,
): boolean => {
  const expected = flueConversationId(principalKey, conversationId);
  const expectedBytes = Buffer.from(expected);
  const presentedBytes = Buffer.from(instanceId);
  if (expectedBytes.length !== presentedBytes.length) return false;
  return timingSafeEqual(expectedBytes, presentedBytes);
};

export const agentOwnershipHeaders = (
  identity: ConversationIdentity,
): Record<string, string> => ({
  [BRUNCH_PRINCIPAL_HEADER]: identity.principalKey,
  [BRUNCH_CONVERSATION_HEADER]: identity.conversationId,
});

/** Identity headers and payload encoding shared by Node and the local Flue UI. */

export { BRUNCH_PRINCIPAL_HEADER } from "@hashintel/brunch-agent-transport-aisdk/headers";

export const BRUNCH_CONVERSATION_HEADER = "x-brunch-conversation";

/** Principal for the stock Flue UI at `/`. Not a second ownership rule. */
export const LOCAL_UI_PRINCIPAL = "local";

export const identityPayload = (
  principalKey: string,
  conversationId: string,
): Uint8Array => {
  const encoder = new TextEncoder();
  const principalBytes = encoder.encode(principalKey);
  const conversationBytes = encoder.encode(conversationId);
  const payload = new Uint8Array(
    principalBytes.length + 1 + conversationBytes.length,
  );
  payload.set(principalBytes, 0);
  payload[principalBytes.length] = 0;
  payload.set(conversationBytes, principalBytes.length + 1);
  return payload;
};

export const hexFromDigest = (digest: ArrayBuffer): string =>
  [...new Uint8Array(digest)]
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");

/**
 * Where the conversation store lives, resolved before the adapter opens it.
 *
 * Anchored to this module's location — the way `app.ts` anchors `uiRoot` —
 * never to the launch directory: a cwd-relative default silently creates a
 * fresh empty database when the app is launched from anywhere else, which is
 * the exact restart-durability failure `db.ts` exists to prevent. From `src/`
 * and from the emitted `dist/` bundle alike, `../.data-wipe-me/` resolves to
 * the package directory.
 *
 * Kept apart from `db.ts` so path policy stays importable without loading the
 * Flue Node runtime and SQLite adapter.
 */

import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const conversationDbFileFrom = (override: string): string =>
  override.endsWith(".db") ? override : join(override, "conversations.db");

export function conversationDbPath(): string {
  // Truthiness, not nullish, on purpose: a set-but-empty override would pass
  // '' through to sqlite(), which opens an anonymous temporary database
  // deleted on close — silently non-durable again.
  const override = process.env.BRUNCH_DEV_DB_PATH;
  return override
    ? override
    : fileURLToPath(
        new URL("../.data-wipe-me/conversations.db", import.meta.url),
      );
}

/**
 * Capture JSON lives beside the Flue sqlite file, named by Flue instance id.
 * The hermetic chat test sets `BRUNCH_CHAT_DB_PATH` (not `BRUNCH_DEV_DB_PATH`),
 * so that directory wins when present.
 */
export function captureStorePath(instanceId: string): string {
  if (instanceId.length === 0) {
    throw new TypeError(
      "A Flue instance id is required for the capture store path.",
    );
  }
  const chatDb = process.env.BRUNCH_CHAT_DB_PATH;
  const directory = dirname(
    chatDb ? conversationDbFileFrom(chatDb) : conversationDbPath(),
  );
  return join(directory, `${instanceId}.json`);
}

/**
 * The substrate's conversation storage — host-authored because Flue requires
 * it of the consuming app.
 *
 * Without this file conversations are process-memory and a restart loses them.
 */

import { sqlite } from "@flue/runtime/node";

import { conversationDbPath } from "./db-path.ts";

export default sqlite(conversationDbPath());

/** Human-readable and UI-message projections of Flue's public conversation snapshot. */

import {
  type FlueConversationMessage,
  type FlueConversationPart,
  type FlueConversationSnapshot,
} from "@flue/sdk";

import {
  CLIENT_TOOL_RESULT_SIGNAL,
  isAwaitingClient,
  providerExecutedFor,
} from "./client-tool.ts";

type UiMessagePart =
  | { readonly type: "text"; readonly text: string; readonly state: "done" }
  | {
      readonly type: "reasoning";
      readonly text: string;
      readonly state: "done";
    }
  | {
      readonly type: `data-${string}`;
      readonly data: unknown;
    }
  | {
      readonly type: "file";
      readonly mediaType: string;
      readonly url: string;
      readonly filename?: string;
    }
  | {
      readonly type: `tool-${string}`;
      readonly toolCallId: string;
      readonly state: "output-available" | "output-error" | "input-available";
      readonly input: unknown;
      readonly output?: unknown;
      readonly errorText?: string;
      readonly providerExecuted?: boolean;
    };

const unhandledConversationPart = (part: never): never => {
  throw new Error(`Unhandled Flue conversation part: ${JSON.stringify(part)}`);
};

const isFlueDataPart = (
  part: FlueConversationPart,
): part is Extract<FlueConversationPart, { type: `data-${string}` }> =>
  part.type.startsWith("data-");

export interface UiHistoryMessage {
  readonly id: string;
  readonly role: "user" | "assistant";
  readonly parts: readonly UiMessagePart[];
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null;

const clientToolResultsFrom = (
  snapshot: FlueConversationSnapshot,
): ReadonlyMap<string, unknown> => {
  const outputsByCallId = new Map<string, unknown>();
  for (const message of snapshot.messages) {
    if (message.purpose !== "dispatch") continue;
    if (message.signal?.tagName !== CLIENT_TOOL_RESULT_SIGNAL) continue;
    const parsed: unknown = (() => {
      try {
        return JSON.parse(
          message.parts
            .filter(
              (part): part is Extract<FlueConversationPart, { type: "text" }> =>
                part.type === "text",
            )
            .map((part) => part.text)
            .join(""),
        ) as unknown;
      } catch {
        return undefined;
      }
    })();
    const results = Array.isArray(parsed) ? parsed : [];
    for (const result of results) {
      if (
        !isRecord(result) ||
        typeof result.toolCallId !== "string" ||
        !("output" in result)
      ) {
        continue;
      }
      outputsByCallId.set(result.toolCallId, result.output);
    }
  }
  return outputsByCallId;
};

const resolveToolOutput = (
  part: Extract<FlueConversationPart, { type: "dynamic-tool" }>,
  clientOutputs: ReadonlyMap<string, unknown>,
): unknown => {
  const clientOutput = clientOutputs.get(part.toolCallId);
  if (part.state === "output-available" && isAwaitingClient(part.output)) {
    return clientOutput;
  }
  if (part.state === "output-available") {
    return part.output;
  }
  return clientOutput;
};

const toolPartFrom = (
  part: Extract<FlueConversationPart, { type: "dynamic-tool" }>,
  clientOutputs: ReadonlyMap<string, unknown>,
): UiMessagePart => {
  const output = resolveToolOutput(part, clientOutputs);
  const providerExecuted =
    part.state === "output-available"
      ? providerExecutedFor(isAwaitingClient(part.output))
      : undefined;
  if (part.state === "output-error") {
    return {
      type: `tool-${part.toolName}`,
      toolCallId: part.toolCallId,
      state: "output-error",
      input: part.input,
      errorText: part.errorText,
      ...(providerExecuted === undefined ? {} : { providerExecuted }),
    };
  }
  if (output !== undefined) {
    return {
      type: `tool-${part.toolName}`,
      toolCallId: part.toolCallId,
      state: "output-available",
      input: part.input,
      output,
      ...(providerExecuted === undefined ? {} : { providerExecuted }),
    };
  }
  return {
    type: `tool-${part.toolName}`,
    toolCallId: part.toolCallId,
    state: "input-available",
    input: part.input,
  };
};

const partsFrom = (
  message: FlueConversationMessage,
  clientOutputs: ReadonlyMap<string, unknown>,
): UiMessagePart[] => {
  const parts: UiMessagePart[] = [];
  for (const part of message.parts) {
    if (part.type === "text") {
      parts.push({ type: "text", text: part.text, state: "done" });
      continue;
    }
    if (part.type === "reasoning") {
      parts.push({ type: "reasoning", text: part.text, state: "done" });
      continue;
    }
    if (part.type === "dynamic-tool") {
      parts.push(toolPartFrom(part, clientOutputs));
      continue;
    }
    if (part.type === "file") {
      parts.push({
        type: "file",
        mediaType: part.mediaType,
        url: part.url ?? "",
        ...(part.filename === undefined ? {} : { filename: part.filename }),
      });
      continue;
    }
    if (isFlueDataPart(part)) {
      parts.push({ type: part.type, data: part.data });
      continue;
    }
    unhandledConversationPart(part);
  }
  return parts;
};

export const snapshotToUiMessages = (
  snapshot: FlueConversationSnapshot,
): UiHistoryMessage[] => {
  const clientOutputs = clientToolResultsFrom(snapshot);
  const messages: UiHistoryMessage[] = [];
  for (const message of snapshot.messages) {
    if (message.display !== "visible") continue;
    if (message.purpose !== "user" && message.purpose !== "assistant") continue;
    if (message.role !== "user" && message.role !== "assistant") continue;
    const parts = partsFrom(message, clientOutputs);
    if (parts.length === 0) continue;
    messages.push({ id: message.id, role: message.role, parts });
  }
  return messages;
};

const textOf = (message: FlueConversationMessage): string =>
  message.parts
    .filter(
      (part): part is Extract<FlueConversationPart, { type: "text" }> =>
        part.type === "text",
    )
    .map((part) => part.text)
    .join("");

const formatToolPart = (
  part: Extract<FlueConversationPart, { type: "dynamic-tool" }>,
  clientOutputs: ReadonlyMap<string, unknown>,
): string => {
  const output = resolveToolOutput(part, clientOutputs);
  const result =
    part.state === "output-error"
      ? `error: ${part.errorText}`
      : output === undefined
        ? "pending"
        : JSON.stringify(output);
  return `- tool ${part.toolName} (${part.toolCallId}): ${result}`;
};

/**
 * Built-in Flue `history()` snapshot → human-readable transcript.
 * User text, assistant text, and tool interactions, including client-tool
 * results delivered as signals.
 */
export const formatFlueTranscript = (
  snapshot: FlueConversationSnapshot,
): string => {
  const clientOutputs = clientToolResultsFrom(snapshot);
  const sections: string[] = [];
  for (const message of snapshot.messages) {
    if (message.purpose === "dispatch") {
      if (message.signal?.tagName !== CLIENT_TOOL_RESULT_SIGNAL) continue;
      const body = textOf(message);
      if (body.length === 0) continue;
      sections.push(`Signal ${CLIENT_TOOL_RESULT_SIGNAL}: ${body}`);
      continue;
    }
    if (message.display !== "visible") continue;
    if (message.purpose !== "user" && message.purpose !== "assistant") continue;
    const speaker = message.purpose === "user" ? "User" : "Assistant";
    const lines: string[] = [];
    const text = textOf(message);
    if (text.length > 0) lines.push(text);
    for (const part of message.parts) {
      if (part.type === "text" || part.type === "reasoning") continue;
      if (part.type === "dynamic-tool") {
        lines.push(formatToolPart(part, clientOutputs));
        continue;
      }
      if (part.type === "file") {
        lines.push(`- file ${part.filename ?? part.mediaType}`);
        continue;
      }
      if (isFlueDataPart(part)) {
        lines.push(
          `- data ${part.type.slice("data-".length)}: ${JSON.stringify(part.data)}`,
        );
        continue;
      }
      unhandledConversationPart(part);
    }
    if (lines.length === 0) continue;
    sections.push(`## ${speaker}\n${lines.join("\n")}`);
  }
  return sections.join("\n\n");
};

/** Project Flue live conversation chunks into AI SDK UI-message-stream chunks. */

import { type ConversationStreamChunk } from "@flue/sdk";

import { providerExecutedFor } from "./client-tool.ts";

import type { UIMessageChunk } from "ai";

export interface FlueUiStreamOptions {
  readonly submissionId: string;
  readonly clientToolNames: ReadonlySet<string>;
  readonly write: (chunk: UIMessageChunk) => void;
}

type StreamingPart = {
  readonly kind: "text" | "reasoning";
  readonly partId: string;
};

const unhandledConversationChunk = (chunk: never): never => {
  throw new Error(
    `Unhandled Flue conversation chunk: ${JSON.stringify(chunk)}`,
  );
};

export const createFlueUiStream = (
  options: FlueUiStreamOptions,
): { accept: (chunk: ConversationStreamChunk) => void } => {
  let accepting = false;
  let messageId: string | undefined;
  let turnId: string | undefined;
  let partOrdinal = 0;
  let streamingPart: StreamingPart | undefined;
  const pendingClientToolCallIds = new Set<string>();

  const finishPart = (): void => {
    if (!streamingPart) return;
    options.write({
      type: `${streamingPart.kind}-end`,
      id: streamingPart.partId,
    });
    streamingPart = undefined;
  };

  const finishTurn = (): void => {
    finishPart();
    if (!turnId) return;
    options.write({ type: "finish-step" });
    turnId = undefined;
  };

  const startPart = (kind: StreamingPart["kind"]): StreamingPart => {
    finishPart();
    partOrdinal += 1;
    const part = {
      kind,
      partId: `${messageId}:${kind}:${partOrdinal}`,
    } as const;
    options.write({ type: `${kind}-start`, id: part.partId });
    streamingPart = part;
    return part;
  };

  return {
    accept(chunk) {
      switch (chunk.type) {
        case "message-started": {
          accepting = chunk.submissionId === options.submissionId;
          if (!accepting) return;

          if (messageId === undefined) {
            messageId = chunk.messageId;
            options.write({ type: "start", messageId });
          }
          finishTurn();
          turnId = chunk.turnId ?? `${messageId}:turn`;
          options.write({ type: "start-step" });
          return;
        }
        case "submission-settled": {
          if (chunk.submissionId !== options.submissionId) return;
          finishTurn();
          switch (chunk.outcome) {
            case "completed":
              options.write({
                type: "finish",
                finishReason:
                  pendingClientToolCallIds.size > 0 ? "tool-calls" : "stop",
              });
              break;
            case "failed":
              options.write({
                type: "error",
                errorText: "The chat turn failed.",
              });
              break;
            case "aborted":
              options.write({
                type: "abort",
                reason: "The chat turn aborted.",
              });
              break;
            default:
              unhandledConversationChunk(chunk.outcome);
          }
          accepting = false;
          return;
        }
        case "conversation-reset":
        case "message-appended":
        case "stream-checkpoint":
          // Observe/reconnect machinery, not assistant-message content. This
          // projector emits one AI SDK assistant message for one Flue
          // submission; these chunks are not parts of that message.
          return;
        case "message-delta": {
          if (!accepting || messageId === undefined) return;
          if (chunk.messageId !== messageId) return;
          const part =
            streamingPart?.kind === chunk.kind
              ? streamingPart
              : startPart(chunk.kind);
          options.write({
            type: `${part.kind}-delta`,
            id: part.partId,
            delta: chunk.delta,
          });
          return;
        }
        case "tool-input": {
          if (!accepting || messageId === undefined) return;
          if (chunk.messageId !== messageId) return;
          finishPart();
          const isClientTool = options.clientToolNames.has(chunk.toolName);
          if (isClientTool) pendingClientToolCallIds.add(chunk.toolCallId);
          const providerExecuted = providerExecutedFor(isClientTool);
          options.write({
            type: "tool-input-available",
            toolCallId: chunk.toolCallId,
            toolName: chunk.toolName,
            input: chunk.input,
            ...(providerExecuted === undefined ? {} : { providerExecuted }),
          });
          return;
        }
        case "tool-output": {
          if (!accepting || messageId === undefined) return;
          if (pendingClientToolCallIds.has(chunk.toolCallId)) return;
          options.write({
            type: "tool-output-available",
            toolCallId: chunk.toolCallId,
            output: chunk.output,
            providerExecuted: true,
          });
          return;
        }
        case "tool-output-error": {
          if (!accepting || messageId === undefined) return;
          if (pendingClientToolCallIds.has(chunk.toolCallId)) return;
          options.write({
            type: "tool-output-error",
            toolCallId: chunk.toolCallId,
            errorText: chunk.errorText,
            providerExecuted: true,
          });
          return;
        }
        case "message-completed": {
          if (!accepting || messageId === undefined) return;
          if (chunk.messageId === messageId) finishTurn();
          return;
        }
        case "message-metadata": {
          if (!accepting || messageId === undefined) return;
          if (chunk.messageId !== messageId) return;
          options.write({
            type: "message-metadata",
            messageMetadata: chunk.metadata,
          });
          return;
        }
        case "data-part": {
          if (!accepting || messageId === undefined) return;
          if (chunk.messageId !== messageId) return;
          options.write({
            type: `data-${chunk.name}`,
            data: chunk.data,
          });
          return;
        }
        default:
          unhandledConversationChunk(chunk);
      }
    },
  };
};

