/** Application composition for Petrinaut's stock AI SDK chat transport. */

import { init } from "@flue/runtime";
import { createFlueClient, type FlueConversationSnapshot } from "@flue/sdk";

import {
  createAiSdkChatHandler,
  type ChatResumeInput,
  type ChatTurnInput,
  type ConversationIdentity,
  type TransportInspectionEvent,
} from "@hashintel/brunch-agent-transport-aisdk";

import { ChatAgent } from "./agents/chat-agent.ts";
import { clientToolNames, CLIENT_TOOL_RESULT_SIGNAL } from "./client-tool.ts";
import {
  agentOwnershipHeaders,
  flueConversationIdFrom,
} from "./conversation-identity.ts";
import { snapshotToUiMessages } from "./flue-transcript.ts";
import { createFlueUiStream } from "./flue-ui-stream.ts";
import { defaultPanelOrigins } from "./local-dev-origins.ts";
import { CHAT_AGENT_ROUTE } from "./routes.ts";

import type { UIMessageChunk } from "ai";

const inspect =
  process.env.BRUNCH_TRANSPORT_AISDK_INSPECT === "1"
    ? (event: TransportInspectionEvent): void => {
        process.stdout.write(`TRANSPORT_AISDK ${JSON.stringify(event)}\n`);
      }
    : undefined;

const appTransport: typeof fetch = async (input, init) => {
  const { default: app } = await import("./app.ts");
  return app.fetch(input instanceof Request ? input : new Request(input, init));
};

const conversationUrl = (instanceId: string): string =>
  `http://brunch.local/agents/${CHAT_AGENT_ROUTE}/${instanceId}`;

const historyClient = (identity: ConversationIdentity) =>
  createFlueClient({
    url: conversationUrl(flueConversationIdFrom(identity)),
    fetch: appTransport,
    headers: agentOwnershipHeaders(identity),
  });

const streamTurn = async (
  instanceId: string,
  dispatch: Parameters<ReturnType<typeof init>["dispatch"]>[0],
  write: (chunk: UIMessageChunk) => void,
): Promise<void> => {
  const agent = init(ChatAgent, { id: instanceId });
  const receipt = await agent.dispatch(dispatch);
  const projector = createFlueUiStream({
    submissionId: receipt.submissionId,
    clientToolNames,
    write,
  });
  await agent.read(receipt, { onEvent: (chunk) => projector.accept(chunk) });
};

const runUserTurn = (
  input: ChatTurnInput,
  write: (chunk: UIMessageChunk) => void,
): Promise<void> =>
  streamTurn(
    flueConversationIdFrom(input),
    { message: input.userMessage.text, idempotencyKey: input.idempotencyKey },
    write,
  );

const runClientToolResume = (
  input: ChatResumeInput,
  write: (chunk: UIMessageChunk) => void,
): Promise<void> =>
  streamTurn(
    flueConversationIdFrom(input),
    {
      message: {
        kind: "signal",
        type: CLIENT_TOOL_RESULT_SIGNAL,
        tagName: CLIENT_TOOL_RESULT_SIGNAL,
        body: JSON.stringify(input.toolResults),
        attributes: {
          toolCallIds: input.toolResults
            .map((result) => result.toolCallId)
            .join(","),
        },
      },
      idempotencyKey: input.idempotencyKey,
    },
    write,
  );

const loadHistory = async (
  identity: ConversationIdentity,
): Promise<{ readonly messages: readonly unknown[] }> => {
  let snapshot: FlueConversationSnapshot;
  try {
    snapshot = await historyClient(identity).history();
  } catch {
    return { messages: [] };
  }
  return { messages: snapshotToUiMessages(snapshot) };
};

export const petrinautChatHandler = createAiSdkChatHandler({
  allowedOrigins: (
    process.env.BRUNCH_PETRINAUT_ORIGINS ?? defaultPanelOrigins.join(",")
  )
    .split(",")
    .map((origin) => origin.trim())
    .filter((origin) => origin.length > 0),
  inspect,
  runTurn: runUserTurn,
  resumeTurn: runClientToolResume,
  loadHistory,
});

/** Browser-facing route segments; conversation identity remains the agent's pinned `agentName`. */

export const CHAT_AGENT_ROUTE = "chat";

/** Stock `DefaultChatTransport` endpoint used by Petrinaut's local panel. */
export const PETRINAUT_CHAT_ROUTE = "/api/chat";

import { defineTool } from "@flue/runtime";
import * as v from "valibot";

export const PING_TOOL_NAME = "ping";

export const ping = defineTool({
  name: PING_TOOL_NAME,
  description:
    "Return a short server-side acknowledgement. Call this when you need to confirm the server is in the loop.",
  input: v.object({
    note: v.optional(v.pipe(v.string(), v.nonEmpty())),
  }),
  output: v.object({
    ok: v.literal(true),
    note: v.string(),
  }),
  run({ data }) {
    return { output: { ok: true as const, note: data.note ?? "pong" } };
  },
});

import { defineTool } from "@flue/runtime";
import * as v from "valibot";

import {
  petrinautDocNames,
  readPetrinautDocToolName,
} from "@hashintel/petrinaut-core/ai";

import { AWAITING_CLIENT } from "../client-tool.ts";

export const READ_PETRINAUT_DOC_TOOL_NAME = readPetrinautDocToolName;

export const readPetrinautDoc = defineTool({
  name: READ_PETRINAUT_DOC_TOOL_NAME,
  description:
    "Read one page of the Petrinaut user guide. The browser executes this tool. After you call it, wait for a client-tool-result signal carrying the page text, then continue from that text.",
  input: v.object({
    doc: v.picklist(petrinautDocNames),
  }),
  output: v.object({
    awaiting: v.literal(AWAITING_CLIENT),
  }),
  run() {
    return { output: { awaiting: AWAITING_CLIENT }, terminate: true };
  },
});

/**
 * Print a human-readable transcript from Flue `history()` for one conversation.
 *
 * Usage, with the Brunch server already running (`yarn dev:brunch`):
 *
 *   yarn workspace @apps/brunch-agent transcript -- --principal <key> --id <conversationId>
 *
 * Identity matches POST /api/chat: principal + conversation id hash to the
 * Flue instance. The mounted URL requires those same values as headers. This
 * is a read of canonical Flue history, not a second log.
 */

import { createFlueClient } from "@flue/sdk";

import {
  agentOwnershipHeaders,
  flueConversationIdFrom,
} from "./conversation-identity.ts";
import { formatFlueTranscript } from "./flue-transcript.ts";
import { defaultChatOrigin } from "./local-dev-origins.ts";
import { CHAT_AGENT_ROUTE } from "./routes.ts";

const readFlag = (
  argv: readonly string[],
  name: string,
): string | undefined => {
  const index = argv.indexOf(name);
  if (index < 0) return undefined;
  const value = argv[index + 1];
  return value === undefined || value.length === 0 ? undefined : value;
};

const argv = process.argv.slice(2);
const principalKey = readFlag(argv, "--principal");
const conversationId = readFlag(argv, "--id");
const origin = readFlag(argv, "--origin") ?? defaultChatOrigin;

if (principalKey === undefined || conversationId === undefined) {
  process.stderr.write(
    "usage: transcript -- --principal <key> --id <conversationId> [--origin <url>]\n",
  );
  process.exit(1);
}

const identity = { principalKey, conversationId };
const instanceId = flueConversationIdFrom(identity);
const snapshot = await createFlueClient({
  url: `${origin}/agents/${CHAT_AGENT_ROUTE}/${instanceId}`,
  headers: agentOwnershipHeaders(identity),
}).history();

process.stdout.write(`${formatFlueTranscript(snapshot)}\n`);

import { useFlueAgent } from "@flue/react";
import {
  createFlueClient,
  type FlueClient,
  type FlueConversationMessage,
} from "@flue/sdk";
import { useEffect, useMemo, useState, type FormEvent } from "react";

import { flueConversationIdWeb } from "../conversation-identity-web.ts";
import {
  BRUNCH_CONVERSATION_HEADER,
  BRUNCH_PRINCIPAL_HEADER,
  LOCAL_UI_PRINCIPAL,
} from "../conversation-payload.ts";
import { CHAT_AGENT_ROUTE } from "../routes.ts";

function VisibleMessage({ message }: { message: FlueConversationMessage }) {
  if (
    message.display !== "visible" ||
    (message.purpose !== "user" && message.purpose !== "assistant")
  ) {
    return null;
  }

  return (
    <article className={`message message--${message.role}`}>
      <p className="message__role">
        {message.role === "user" ? "You" : "Assistant"}
      </p>
      {message.parts.map((part, partIndex) => {
        if (part.type === "text") {
          return (
            // oxlint-disable-next-line react/no-array-index-key -- Flue text parts expose no stable identifier.
            <p className="message__text" key={partIndex}>
              {part.text}
            </p>
          );
        }
        return null;
      })}
    </article>
  );
}

function ChatConversation({ client }: { client: FlueClient }) {
  const [input, setInput] = useState("");
  const agent = useFlueAgent({ client });

  const busy =
    agent.status === "connecting" ||
    agent.status === "submitted" ||
    agent.status === "streaming";

  function submit(event: FormEvent<HTMLFormElement>): void {
    event.preventDefault();
    const reply = input.trim();
    if (!reply || busy) return;
    setInput("");
    void agent.sendMessage(reply);
  }

  return (
    <main className="shell">
      <header className="masthead">
        <div>
          <p className="eyebrow">Brunch / Flue chat</p>
          <h1>Plain Flue conversation</h1>
        </div>
        <span className={`status status--${agent.status}`}>{agent.status}</span>
      </header>

      <section className="transcript" aria-live="polite" aria-busy={busy}>
        {agent.messages.map((message) => (
          <VisibleMessage key={message.id} message={message} />
        ))}
        {agent.error ? <p className="error">{agent.error.message}</p> : null}
      </section>

      <form className="composer" onSubmit={submit}>
        <label htmlFor="reply">Your message</label>
        <div className="composer__row">
          <textarea
            id="reply"
            value={input}
            onChange={(event) => setInput(event.target.value)}
            placeholder="Ask something."
            rows={3}
          />
          <button type="submit" disabled={busy || input.trim().length === 0}>
            Send
          </button>
        </div>
      </form>
    </main>
  );
}

export function Chat() {
  const conversationId = useMemo(() => crypto.randomUUID(), []);
  const [client, setClient] = useState<FlueClient>();

  useEffect(() => {
    let cancelled = false;
    void flueConversationIdWeb(LOCAL_UI_PRINCIPAL, conversationId).then(
      (instanceId) => {
        if (cancelled) return;
        setClient(
          createFlueClient({
            url: `/agents/${CHAT_AGENT_ROUTE}/${instanceId}`,
            headers: {
              [BRUNCH_PRINCIPAL_HEADER]: LOCAL_UI_PRINCIPAL,
              [BRUNCH_CONVERSATION_HEADER]: conversationId,
            },
          }),
        );
      },
    );
    return () => {
      cancelled = true;
    };
  }, [conversationId]);

  if (client === undefined) {
    return (
      <main className="shell">
        <header className="masthead">
          <div>
            <p className="eyebrow">Brunch / Flue chat</p>
            <h1>Plain Flue conversation</h1>
          </div>
          <span className="status status--connecting">connecting</span>
        </header>
      </main>
    );
  }

  return <ChatConversation client={client} />;
}

